create or replace function public.sync_installment_from_payment_request() returns trigger language plpgsql security definer set search_path=public as $$ declare inst public.order_installments; remaining numeric; applied numeric; begin if new.status not in ('approved','completed','paid') or new.related_payment_id is null then return new; end if; remaining:=coalesce(new.amount,0); if remaining<=0 then return new; end if; for inst in select * from public.order_installments where order_id=(select o.id from public.payments p join public.orders o on o.payment_reference=p.payment_reference where p.id=new.related_payment_id limit 1) and balance>0 order by installment_number for update loop applied:=least(inst.balance,remaining); update public.order_installments set amount_paid=amount_paid+applied,status=case when amount_paid+applied>=amount_due then 'paid' else 'partial' end,payment_id=new.related_payment_id,payment_reference=new.reference,paid_at=case when amount_paid+applied>=amount_due then now() else paid_at end,updated_at=now() where id=inst.id; remaining:=remaining-applied; exit when remaining<=0; end loop; return new; end; $$;
revoke all on function public.sync_installment_from_payment_request() from public; drop trigger if exists trg_sync_installment_from_payment_request on public.payment_requests; create trigger trg_sync_installment_from_payment_request after update of status on public.payment_requests for each row execute function public.sync_installment_from_payment_request();
